// Fixed SDK AuthFetch + test-only HTTP fixture + synthetic FCM provider.
import {spawn} from 'node:child_process';import {createInterface} from 'node:readline';import {pathToFileURL} from 'node:url';import {mkdtemp,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import {join} from 'node:path';import {once} from 'node:events';import assert from 'node:assert/strict';
const sdk=process.env.SDK_SOURCE_DIR,{AuthFetch}=await import(pathToFileURL(`${sdk}/src/auth/clients/AuthFetch.ts`));const {default:ProtoWallet}=await import(pathToFileURL(`${sdk}/src/wallet/ProtoWallet.ts`));const {default:PrivateKey}=await import(pathToFileURL(`${sdk}/src/primitives/PrivateKey.ts`));
function deadline(promise,label){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error(`${label} timeout`)),8000);promise.then(value=>{clearTimeout(timer);resolve(value)},error=>{clearTimeout(timer);reject(error)})});}
const dir=await mkdtemp(join(tmpdir(),'messagebox-fcm-http-'));const child=spawn(process.env.FCM_HTTP_FIXTURE,[],{stdio:['ignore','pipe','inherit'],env:{...process.env,FCM_TEST_DIR:dir}}),exited=once(child,'exit');
try{const lines=createInterface({input:child.stdout})[Symbol.asyncIterator](),first=await deadline(Promise.race([lines.next(),exited.then(([code,signal])=>({early:{code,signal}}))]),'startup');assert.ok(!first.early&&!first.done);const port=Number(first.value),bob=new PrivateKey(4).toPublicKey().toString(),server=new PrivateKey(3).toPublicKey().toString(),auth=new AuthFetch(new ProtoWallet(new PrivateKey(2)),undefined,undefined,undefined,{responseTimeoutMs:3000});const response=await auth.fetch(`http://127.0.0.1:${port}/sendMessage`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:{recipient:bob,messageBox:'notifications',messageId:'fcm-http-id',body:'private test body'}}),requireMutualAuth:true,expectedIdentityKey:server,allowPayments:false});assert.equal(response.status,200);const eventLine=await deadline(Promise.race([lines.next(),exited.then(([code,signal])=>({early:{code,signal}}))]),'fake provider event');assert.ok(!eventLine.early&&!eventLine.done);const event=JSON.parse(eventLine.value).fakeFcm;assert.equal(event.token,'fake-fcm-token');assert.equal(event.android.data.messageId,'fcm-http-id');assert.equal(event.notification.title,'New Message');assert.equal(event.notification.body,'Open the app to view this message.');assert.ok(!JSON.stringify(event).includes('private test body'));console.log('Fixed SDK signed HTTP notification send invoked a fake provider after commit; no Firebase/network provider.');}finally{child.kill('SIGKILL');await exited.catch(()=>{});await rm(dir,{recursive:true,force:true});}
